PRAGMA foreign_keys = ON;

-- Handbook remediation: keep the series but make every metric explain source, context, and interpretation.
UPDATE metrics
SET type = CASE WHEN type = 'body_fat' THEN 'score' ELSE type END,
    recorded_at = CASE WHEN recorded_at >= '2026-09-01T09:00:00+08:00'
      THEN printf('2026-08-%02dT07:%02d:00+08:00', 1 + ((CAST(substr(metric_id, -5) AS INTEGER) - 1) % 28), CAST(substr(metric_id, -5) AS INTEGER) % 60)
      ELSE recorded_at END,
    value_text =
      CASE type
        WHEN 'sleep_minutes' THEN 'sleep_minutes=' || value || '; source=wearable_night_summary'
        WHEN 'steps' THEN 'steps=' || value || '; source=wearable_daily_total'
        WHEN 'heart_rate' THEN 'resting_heart_rate=' || value || '; source=wearable_morning_sample'
        ELSE 'calf_edema_score=' || value || '; source=self_report_checkin' END
      || '; context=' || CASE (CAST(substr(metric_id, -5) AS INTEGER) % 15)
        WHEN 0 THEN 'preflight_day' WHEN 1 THEN 'postflight_morning' WHEN 2 THEN 'standby_day' WHEN 3 THEN 'hotel_rest_day'
        WHEN 4 THEN 'commute_heavy_day' WHEN 5 THEN 'training_day' WHEN 6 THEN 'recovery_only_day' WHEN 7 THEN 'household_day'
        WHEN 8 THEN 'early_report_day' WHEN 9 THEN 'late_arrival_day' WHEN 10 THEN 'timezone_transition' WHEN 11 THEN 'weather_indoor_day'
        WHEN 12 THEN 'cycle_sensitive_window' WHEN 13 THEN 'equipment_free_day' ELSE 'ordinary_off_day' END
      || '; interpretation=' || CASE CAST((CAST(substr(metric_id, -5) AS INTEGER) - 1) / 15 AS INTEGER)
        WHEN 0 THEN 'complete_record' WHEN 1 THEN 'duty_steps_not_training' WHEN 2 THEN 'compare_with_prior_three_days'
        WHEN 3 THEN 'sleep_window_fragmented' WHEN 4 THEN 'fatigue_context_required' WHEN 5 THEN 'edema_context_required'
        WHEN 6 THEN 'rpe_context_required' WHEN 7 THEN 'no_diagnosis_from_single_value' WHEN 8 THEN 'use_for_deload_decision'
        WHEN 9 THEN 'use_for_recovery_window' WHEN 10 THEN 'cross_check_calendar' WHEN 11 THEN 'cross_check_flight_roster'
        WHEN 12 THEN 'private_health_only' WHEN 13 THEN 'historical_closed' ELSE 'baseline_comparison' END
      || '; recorded_at=' || recorded_at
WHERE metric_id LIKE 'met_%';
UPDATE workouts
SET started_at = CASE WHEN started_at >= '2026-09-01T09:00:00+08:00'
      THEN printf('2026-08-%02dT19:%02d:00+08:00', 1 + ((CAST(substr(workout_id, -3) AS INTEGER) - 1) % 28), CAST(substr(workout_id, -3) AS INTEGER) % 60)
      ELSE started_at END;

-- This pre-kickoff resting-heart-rate reading is a distinct same-morning
-- baseline, not another generic historical preflight sample.
UPDATE metrics
SET value_text = 'resting_heart_rate=62; source=wearable_morning_sample; context=plan_start_morning_baseline; interpretation=preplan_reference_only; recorded_at=2026-09-01T07:20:00+08:00'
WHERE metric_id = 'met_hr_baseline_0901';
